153		repeat := createTask(t, h, "dev-1", taskBody("req-1", 30), http.StatusOK)
154		if repeat.ID != task.ID || !repeat.CreatedAt.Equal(task.CreatedAt) {
155			t.Fatalf("repeat returned a different task: %+v vs %+v", repeat, task)
