296			reportBody("rcpt-1", claim.Credential, true, "", `{"ok":true}`), http.StatusConflict)
297	
298		// The timeout released the device; after the backoff it can be claimed again.
299		*clock = clock.Add(2 * time.Second)
300		claim = claimTask(t, h, "dev-1", http.StatusOK)
301		if claim.Attempt != 2 {
302			t.Fatalf("attempt = %d, want 2", claim.Attempt)
