320			*clock = clock.Add(time.Duration(2+i) * time.Second)
321		}
322		task := getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
323		if task.Status != "failed" || task.FailureReason != "deadline exceeded" {
