150	type deviceState struct {
151		device         Device
152		events         []Event                // retained history, ascending sequence (events[i].Sequence = eventBase + i + 1)
153		eventBase      int64                  // number of oldest events removed by retention; sequence of events[0] is eventBase+1
154		maxEvents      int64                  // retention cap; 0 means unlimited
155		known          map[string]knownSample // eventId -> first sample ever received (survives trimming)
156		batches        map[string]storedBatch
157		rules          map[string]*ruleState
158		alerts         []*Alert // per-device, ordered by alert id (id = index + 1)
159		config         *configState
160		tasks          []*taskState          // per-device, ordered by task id (id = index + 1)
161		tasksByRequest map[string]*taskState // requestId -> first task
162	}
