164	// maxSequence is the highest receive sequence ever assigned to the device. It
165	// never retreats: trimming removes events but keeps consuming nothing, and new
166	// samples continue after it.
167	func (state *deviceState) maxSequence() int64 {
168		return state.eventBase + int64(len(state.events))
169	}
170	
171	// earliestSequence returns the first currently retained sequence, or 0 when
172	// the history is empty.
173	func (state *deviceState) earliestSequence() int64 {
174		if len(state.events) == 0 {
175			return 0
176		}
177		return state.eventBase + 1
178	}
179	
180	// retentionStatus snapshots the retention view of the device.
181	func (state *deviceState) retentionStatus() RetentionStatus {
182		status := RetentionStatus{
183			MaxEvents:      state.maxEvents,
184			RetainedEvents: int64(len(state.events)),
185			MaxSequence:    state.maxSequence(),
186		}
187		if earliest := state.earliestSequence(); earliest != 0 {
188			status.EarliestSequence = &earliest
189		}
190		return status
191	}
192	
193	// planTrimThrough reports the cumulative count of oldest events that must be
194	// removed for the history to satisfy maxEvents after a write that leaves
195	// maxSequence at maxSeq. It only grows: raising the limit or going unlimited
196	// never brings trimmed events back.
197	func planTrimThrough(eventBase, maxSeq, maxEvents int64) int64 {
198		if maxEvents == 0 {
199			return eventBase
200		}
201		if through := maxSeq - maxEvents; through > eventBase {
202			return through
203		}
204		return eventBase
205	}
206	
207	// applyTrim drops oldest retained events through sequence trimThrough. It
208	// touches neither deduplication records nor any other device state.
209	func (state *deviceState) applyTrim(trimThrough int64) {
210		if trimThrough <= state.eventBase {
211			return
212		}
213		drop := trimThrough - state.eventBase
214		if drop > int64(len(state.events)) {
215			drop = int64(len(state.events))
216		}
217		// Drop the prefix without preserving its backing slots.
218		remaining := make([]Event, len(state.events)-int(drop))
219		copy(remaining, state.events[drop:])
220		state.events = remaining
221		state.eventBase += drop
222	}
