517	// --- rules and alerts -------------------------------------------------------
518	
519	// ruleUpdate carries the mutable fields of a rule update. A nil pointer leaves
520	// the field unchanged.
521	type ruleUpdate struct {
522		Metric  *string
523		Trigger *float64
524		Recover *float64
525		Enabled *bool
526	}
527	
528	// AlertFilter narrows an alert listing. An empty string or nil pointer leaves
529	// that dimension unfiltered.
530	type AlertFilter struct {
531		RuleID       string
532		Status       string
533		Acknowledged *bool
534	}
535	
536	// CreateRule registers a new enabled rule on a device. Version starts at 1.
537	// It returns ErrDeviceNotFound for an unknown device and ErrRuleConflict when
538	// the device already has a rule with that id.
539	func (s *Store) CreateRule(id, ruleID, metric string, trigger, recover float64) (Rule, error) {
540		s.mu.Lock()
541		defer s.mu.Unlock()
542		state, ok := s.devices[id]
543		if !ok {
544			return Rule{}, ErrDeviceNotFound
545		}
546		if _, exists := state.rules[ruleID]; exists {
547			return Rule{}, ErrRuleConflict
548		}
549		now := s.now().UTC()
550		rule := Rule{
551			ID: ruleID, Metric: metric, Trigger: trigger, Recover: recover,
552			Enabled: true, Version: 1, CreatedAt: now, UpdatedAt: now,
553		}
554		if s.wal != nil {
555			if err := s.wal.appendRecord(recRule, walRule{DeviceID: id, Rule: rule}); err != nil {
556				return Rule{}, storageUnavailable(err)
557			}
558		}
559		state.rules[ruleID] = &ruleState{rule: rule}
560		return cloneRule(rule), nil
561	}
562	
563	// UpdateRule applies a version-checked optimistic update. A version mismatch
564	// returns ErrVersionConflict with state unchanged. Every successful update
565	// bumps the version by one and immediately ends the rule's active alert (if
566	// any) with reason rule_changed; the rule starts again with no active alert.
567	func (s *Store) UpdateRule(id, ruleID string, update ruleUpdate, version int64) (Rule, []*Alert, error) {
568		s.mu.Lock()
569		defer s.mu.Unlock()
570		state, ok := s.devices[id]
571		if !ok {
572			return Rule{}, nil, ErrDeviceNotFound
573		}
574		rs, ok := state.rules[ruleID]
575		if !ok {
576			return Rule{}, nil, ErrRuleNotFound
577		}
578		if rs.rule.Version != version {
579			return Rule{}, nil, ErrVersionConflict
580		}
581	
582		updated := rs.rule
583		if update.Metric != nil {
584			updated.Metric = *update.Metric
585		}
586		if update.Trigger != nil {
587			updated.Trigger = *update.Trigger
588		}
589		if update.Recover != nil {
590			updated.Recover = *update.Recover
591		}
592		if update.Enabled != nil {
593			updated.Enabled = *update.Enabled
594		}
595		if updated.Recover >= updated.Trigger {
596			return Rule{}, nil, ErrInvalidRule
597		}
598	
599		// End the active alert of the old version before publishing the new one.
600		var ended []*Alert
601		if rs.activeAlertID != 0 {
602			alert := cloneAlert(*state.alerts[rs.activeAlertID-1])
603			alert.Status = alertStatusEnded
604			alert.EndReason = endReasonRuleChanged
605			now := s.now().UTC()
606			alert.EndedAt = &now
607			ended = append(ended, &alert)
608			rs.activeAlertID = 0
609		}
610	
611		updated.Version++
612		updated.UpdatedAt = s.now().UTC()
613	
614		if s.wal != nil {
615			if err := s.wal.appendRecord(recRule, walRule{DeviceID: id, Rule: updated, Ended: ended}); err != nil {
616				return Rule{}, nil, storageUnavailable(err)
617			}
618		}
619		rs.rule = updated
620		for _, alert := range ended {
621			state.alerts[alert.ID-1] = alert
622		}
623		return cloneRule(updated), cloneAlerts(ended), nil
624	}
625	
626	// GetRule returns one rule.
627	func (s *Store) GetRule(id, ruleID string) (Rule, error) {
628		s.mu.RLock()
629		defer s.mu.RUnlock()
630		state, ok := s.devices[id]
631		if !ok {
632			return Rule{}, ErrDeviceNotFound
633		}
634		rs, ok := state.rules[ruleID]
635		if !ok {
636			return Rule{}, ErrRuleNotFound
637		}
638		return cloneRule(rs.rule), nil
