	state.ensureTasks()
	views := make([]TaskView, 0, len(state.tasks))
	for _, ts := range state.tasks {
		views = append(views, taskView(ts.task))
	}
	sort.Slice(views, func(i, j int) bool { return views[i].ID < views[j].ID })
	return views, nil
}

